let materialView='all';
function storedStringArray(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value.map(String):[];}catch(error){return [];}}
function materialKey(item){return String(item.item||'')+'|'+String(item.category||'');}
