function toggleMaterialFavorite(idx){const key=materialKey(materials[idx]);const favorites=materialFavorites();if(favorites.has(key))favorites.delete(key);else favorites.add(key);localStorage.setItem(FAVORITES_KEY,JSON.stringify([...favorites]));renderMaterials();}
