  list.forEach(m=>{const globalIndex=materials.indexOf(m); const row=document.createElement('div'); const alreadySelected=selected.some(item=>materialKey(item)===materialKey(m)); row.className='matRow'+(alreadySelected?' inSelection':''); row.innerHTML=`<div><div class="matName">${escapeHtml(m.item)}</div><div class="cat">${escapeHtml(m.category)}${alreadySelected?' • In BOM':''}</div></div><button class="favoriteBtn ${favorites.has(materialKey(m))?'active':''}" type="button" aria-label="Favorite ${escapeHtml(m.item)}" onclick="toggleMaterialFavorite(${globalIndex})">★</button><div class="cost">${money(m.cost)}</div><input class="qty" id="qty_${globalIndex}" type="number" min="0" step="1" value="1" onkeydown="if(event.key==='Enter'){event.preventDefault();addItem(${globalIndex});}"><button class="btn add" onclick="addItem(${globalIndex})">${alreadySelected?'Add more':'Add'}</button>`; box.appendChild(row);});
  if(!list.length) box.innerHTML='<div class="empty">No items match that search.</div>';
