function addItem(idx){const qty=normalizeQuantity(document.getElementById('qty_'+idx)?.value||1); if(!qty){showNotice('Enter a quantity greater than zero.','warning'); return;} const m=materials[idx]; const found=selected.find(x=>x.item===m.item && x.category===m.category); if(found) found.qty=Math.min(MAX_ITEM_QUANTITY,found.qty+qty); else selected.push({...m,qty}); rememberRecentMaterial(m); persist(); renderSelected();renderMaterials();showNotice(`${m.item} added to the BOM.`,'success');}
