function isRepair(row){return String(row.category).trim().toLowerCase()==='repairs' || String(row.category).trim().toLowerCase()==='drywall repair';}
function roundMoney(value){return Math.round((Number.isFinite(Number(value))?Number(value):0)*100)/100;}
function effectiveQuoteRows(){return VenturePricing.effectiveRows(selected);}
function totals(){return VenturePricing.calculateTotals(selected,currentMaterialMarkup(),currentLaborMultiplier());}
function customerPricingBreakdown(t){
  const multiplier=1+currentMaterialMarkup();
  const groups=[
    {key:'materials',base:Number(t.materialServicesBase)||0},
    {key:'labor',base:Number(t.laborAdjusted)||0},
    {key:'fees',base:Number(t.adminFeeBase)||0}
  ].map(group=>{
    const rawCents=Math.max(0,group.base*multiplier*100);
    return {...group,cents:Math.floor(rawCents),fraction:rawCents-Math.floor(rawCents)};
  });
  let remaining=Math.round((Number(t.grand)||0)*100)-groups.reduce((sum,group)=>sum+group.cents,0);
  groups.slice().sort((a,b)=>b.fraction-a.fraction).forEach(group=>{if(remaining>0){group.cents++; remaining--;}});
  if(remaining!==0){
    const target=groups.slice().sort((a,b)=>b.base-a.base)[0];
    if(target) target.cents+=remaining;
  }
  return Object.fromEntries(groups.map(group=>[group.key,roundMoney(group.cents/100)]));
}
function renderBomPreview(){const box=document.getElementById('bomPreview'); if(!box) return; const bomItems=selected.filter(r=>!isLabor(r)&&!isFee(r)); const totalQty=bomItems.reduce((sum,r)=>sum+(Number(r.qty)||0),0); if(!bomItems.length){box.innerHTML=`<div class="bomPreviewHead"><b>BOM Preview</b><span class="small">Material-only list will appear here</span></div><div class="empty">Add materials to preview the BOM here.</div>`; return;} box.innerHTML=`<div class="bomPreviewHead"><b>BOM Preview</b><span class="small">${bomItems.length} line item${bomItems.length===1?'':'s'} • ${totalQty} total qty • no costs shown</span></div><div class="bomPreviewBody"><table class="bomPreviewTable"><thead><tr><th>Qty</th><th>Material Item</th><th>Category</th></tr></thead><tbody>${bomItems.map(r=>`<tr><td class="qty">${escapeHtml(r.qty)}</td><td><b>${escapeHtml(itemWithConduitLength(r))}</b></td><td>${escapeHtml(r.category)}</td></tr>`).join('')}</tbody></table></div>`;}
function updateCostDashboard(){
  const t=totals();
  const beforeMarkup=t.beforeMarkup;
  const totalMarkup=t.markupAmount;
  const values={
    dashboardMaterials:t.materialBase,
    dashboardRepairs:t.repairBase,
    dashboardFees:t.adminFeeBase,
    dashboardLabor:t.laborAdjusted,
    dashboardBeforeMarkup:beforeMarkup,
    dashboardMarkup:totalMarkup,
    dashboardAfterMarkup:t.grand
  };
  Object.entries(values).forEach(([id,val])=>{
    const el=document.getElementById(id);
    if(el) el.textContent=money(Number.isFinite(Number(val))?Number(val):0);
  });
  const lines=document.getElementById('dashboardItems');
  if(lines) lines.textContent=String(selected.filter(r=>(Number(r.qty)||0)>0).length);
  const rate=document.getElementById('dashboardMarkupRate');
  const pricingMode=currentPricingMode();
  if(rate) rate.textContent=pricingMode==='at-cost'?'At-cost mode • no labor multiplier • no end markup':pricingMode==='labor-only'?'Labor 1.3× • no end markup':'Labor 1.3× first • '+materialMarkupLabel()+' end markup on entire subtotal';
  const beforeMarkupNote=document.getElementById('dashboardBeforeMarkupNote');
  if(beforeMarkupNote) beforeMarkupNote.textContent=currentLaborMultiplier()===1?'Materials, fees, repairs, and labor at base cost':'Materials, fees, repairs, and labor after 1.3×';
}
function renderSelected(){
  const automaticRows=effectiveQuoteRows().filter(row=>row.automatic);
  const itemRows=selected.map((row,index)=>`<tr><td><b>${escapeHtml(row.item)}</b><br><span class="small">Unit cost ${money(row.cost)}</span></td><td><input type="number" min="0" step="1" value="${row.qty}" onchange="updateQty(${index},this.value)"></td><td>${escapeHtml(row.category)}</td><td class="money">${VenturePricing.isTrenchMinimum(row)?'Calculated below':money((Number(row.cost)||0)*(Number(row.qty)||0))}</td><td><button class="btn danger" onclick="removeItem(${index})">X</button></td></tr>`).join('');
  const adjustmentRows=automaticRows.map(row=>`<tr class="automaticRow"><td><b>${escapeHtml(row.item)}</b><br><span class="small">Automatically enforces the $1,200 trench minimum</span></td><td>1</td><td>Trench</td><td class="money">${money(row.cost)}</td><td></td></tr>`).join('');
  const html=!selected.length?'<div class="empty">No items selected yet.</div>':`<table class="selectedTable"><thead><tr><th>Item</th><th>Qty</th><th>Category</th><th>Line Total</th><th></th></tr></thead><tbody>${itemRows}${adjustmentRows}</tbody></table>`;
  const wrap=document.getElementById('selectedWrap'); if(wrap) wrap.innerHTML=html;
  const projectWrap=document.getElementById('projectSelectedWrap'); if(projectWrap) projectWrap.innerHTML=html;
  const t=totals();
  [['materialSellTotal',t.materialSell],['laborSellTotal',t.laborSell],['feeTotal',t.fees],['grandTotal',t.grand],['projectMaterialSellTotal',t.materialSell],['projectLaborSellTotal',t.laborSell],['projectFeeTotal',t.fees],['projectGrandTotal',t.grand]].forEach(([id,val])=>{const el=document.getElementById(id); if(el) el.textContent=money(val);});
  renderBomPreview(); updateSummaryDock(); updateCostDashboard(); updateCurrentProjectStatus(); renderQuoteReadiness();
}

function quoteValidationIssues(){const project=getProjectInfo();return VenturePricing.validateProject({...project,scopeOfWork:document.getElementById('scopeOfWork')?.value||'',rows:selected});}
function renderQuoteReadiness(){const box=document.getElementById('quoteReadiness');if(!box)return;const issues=quoteValidationIssues();const trench=totals().trenchAdjustment;box.classList.toggle('warning',issues.length>0);box.innerHTML=issues.length?`<b>Complete these items before exporting:</b><ul>${issues.map(issue=>`<li>${escapeHtml(issue.message)}</li>`).join('')}</ul>`:`<b>Ready to export.</b>${trench>0?` Automatic trench minimum adjustment: ${money(trench)}.`:''}`;}
function ensureDocumentReady(){const issues=quoteValidationIssues();if(!issues.length)return true;renderQuoteReadiness();showWorkspaceTab('documents');showNotice('Complete the quote readiness items before exporting.','warning');return false;}
function optionChecked(id,defaultValue=true){const input=document.getElementById(id);return input?input.checked:defaultValue;}



const PRESET_STORAGE_KEY = 'vh_scopePresets';
function savedScopePresets(){try{return JSON.parse(localStorage.getItem(PRESET_STORAGE_KEY) || '{}') || {};}catch(e){return {};}}
function setSavedScopePresets(presets){localStorage.setItem(PRESET_STORAGE_KEY, JSON.stringify(presets || {})); updatePresetStatus();}
function presetCleanItem(row){return {item:String(row.item||''), category:String(row.category||''), qty:Number(row.qty)||1};}
function normalizePresetScopeName(name){return String(name||'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function findSavedPreset(scope){
  const presets=savedScopePresets();
  if(presets[scope]) return {key:scope, preset:presets[scope]};
  const target=normalizePresetScopeName(scope);
  const key=Object.keys(presets).find(k=>normalizePresetScopeName(k)===target);
  return key ? {key, preset:presets[key]} : null;
}
function resolvePresetLine(line){
  const match=materials.find(m=>m.item===line.item && m.category===line.category) || materials.find(m=>m.item===line.item);
  if(!match) return null;
  return {...match, qty:Number(line.qty)||1};
}
function currentPresetScope(){
  const current=selectedWorkType();
  if(current) return current;
  const typed=prompt('Which existing work type should this preset be saved under?');
  return (typed||'').trim();
}

function autoApplyPresetEnabled(){return localStorage.getItem('vh_autoApplyPreset') !== 'false';}
function presetNames(){return Object.keys(savedScopePresets()).sort();}
function applyPresetByScope(scope, opts={}){
  scope=String(scope||'').trim();
  if(!scope) return false;
  const found=findSavedPreset(scope);
  if(!found || !found.preset || !Array.isArray(found.preset.items)) return false;
  const preset=found.preset;
  const displayScope=found.key || scope;
  const resolved=[]; const missing=[];
  preset.items.forEach(line=>{const r=resolvePresetLine(line); if(r) resolved.push(r); else missing.push(line.item);});
  if(!resolved.length){
    if(!opts.silent) alert('Preset could not be applied because none of its items matched the current material list.');
    return false;
  }
  if(selected.length && opts.confirmReplace!==false){
    if(!confirm('This project already contains materials. Replace the current selection with the saved preset for "'+displayScope+'"?')) return false;
  }
  selected=mergeDupes(resolved);
  persist(); renderSelected(); updatePresetStatus();
  if(missing.length && !opts.silent) alert('Preset applied, but '+missing.length+' item(s) no longer matched the material list:\n\n'+missing.join('\n'));
  return true;
}
function maybeAutoApplyPresetForWorkType(scope){
  if(!autoApplyPresetEnabled()) return;
  scope=String(scope||'').trim();
  if(!scope || scope==='__other__') return;
  if(!findSavedPreset(scope)) return;
  applyPresetByScope(scope,{silent:true,confirmReplace:true});
}
function populatePresetPicker(){
  const picker=document.getElementById('presetPicker');
  if(!picker) return;
  const current=picker.value;
  picker.innerHTML='<option value="">Select saved preset...</option>';
  presetNames().forEach(name=>{const o=document.createElement('option'); o.value=name; o.textContent=name; picker.appendChild(o);});
  if(current && savedScopePresets()[current]) picker.value=current;
}
function applyPresetFromPicker(){
  const picker=document.getElementById('presetPicker');
  const scope=(picker?.value||'').trim();
  if(!scope){alert('Choose a saved preset first.'); return;}
  applyPresetByScope(scope,{silent:false,confirmReplace:true});
}

function saveSelectionAsPreset(){
  if(!selected.length){alert('Build a selection first, then save it as a preset.'); return;}
  let scope=currentPresetScope();
  if(!scope){alert('Select a work type first, then try again.'); return;}
  const typed=prompt('Save current selection as preset for this work type:', scope);
  if(typed===null) return;
  scope=String(typed||'').trim();
  if(!scope){alert('Preset was not saved because no work type was entered.'); return;}
  const presets=savedScopePresets();
  const existing=presets[scope];
  if(existing && !confirm('Replace the existing preset for "'+scope+'"?')) return;
  presets[scope]={
    scope,
    updatedAt:new Date().toISOString(),
    items:selected.map(presetCleanItem)
  };
  setSavedScopePresets(presets);
  populatePresetPicker();
  alert('Preset saved for '+scope+' with '+selected.length+' line item'+(selected.length===1?'':'s')+'.');
}
function applySavedPreset(){
  let scope=currentPresetScope();
  if(!scope){alert('Select a work type first.'); return;}
  const presets=savedScopePresets();
  if(!presets[scope]){
    const names=presetNames();
    if(!names.length){alert('No saved presets yet. Build a BOM and click Save Current Selection as Preset first.'); return;}
    const choice=prompt('No preset found for "'+scope+'". Enter one of these preset names:\n\n'+names.join('\n'), names[0]);
    if(choice===null) return;
    scope=String(choice||'').trim();
  }
  if(!findSavedPreset(scope)){alert('Preset not found.'); return;}
  applyPresetByScope(scope,{silent:false,confirmReplace:true});
}
function deleteSavedPreset(){
  let scope=currentPresetScope();
  const presets=savedScopePresets();
  if(!presets[scope]){
    const names=Object.keys(presets).sort();
    if(!names.length){alert('No saved presets to delete.'); return;}
    const choice=prompt('Enter preset to delete:\n\n'+names.join('\n'), names[0]);
    if(choice===null) return;
    scope=String(choice||'').trim();
  }
  if(!presets[scope]){alert('Preset not found.'); return;}
  if(!confirm('Delete saved preset for "'+scope+'"?')) return;
  delete presets[scope]; setSavedScopePresets(presets); populatePresetPicker(); alert('Preset deleted.');
}
function exportSavedPresets(){
  const presets=savedScopePresets();
  const count=Object.keys(presets).length;
  if(!count){alert('No saved presets to export yet.'); return;}
  const payload={app:'Venture Home Estimator Pro',version:APP_VERSION,exportedAt:new Date().toISOString(),presets};
  downloadBlob(JSON.stringify(payload,null,2),'venture_home_scope_presets.json','application/json');
}
function updatePresetStatus(){
  populatePresetPicker();
  const el=document.getElementById('presetStatus'); if(!el) return;
  const scope=selectedWorkType(); const presets=savedScopePresets();
  if(scope && presets[scope]){
    const n=(presets[scope].items||[]).length;
    el.innerHTML='<b>Saved preset available:</b> '+escapeHtml(scope)+' • '+n+' line item'+(n===1?'':'s')+'.';
  } else if(scope){
    el.innerHTML='<b>No saved preset yet for:</b> '+escapeHtml(scope)+'. Build a selection and save it when ready.';
  } else {
    el.textContent='Select a work type, build a BOM, then save it as that work type preset.';
  }
}

