  localStorage.setItem('vh_photoDrawTool', tool || 'select');
  document.querySelectorAll('[data-photo-tool]').forEach(btn=>btn.classList.toggle('active', btn.dataset.photoTool===currentDrawTool()));
  const canvas=document.getElementById('photoCanvas');
