  canvas.addEventListener('touchmove', e=>{e.preventDefault(); moveDiagramAction(e.touches[0]);},{passive:false});
  window.addEventListener('touchend', endDiagramAction);
  document.getElementById('diagramSaveTitle')?.addEventListener('input',()=>{if(diagramObjects.length)markDiagramChanged();});
  setDiagramTool('select');
  redrawDiagramCanvas();
