function duplicateSelectedDiagramObject(){if(diagramSelected<0)return;pushDiagramHistory();const o=cloneMedia(diagramObjects[diagramSelected]);o.x+=25;o.y+=25;if(o.x2!==undefined)o.x2+=25;if(o.y2!==undefined)o.y2+=25;diagramObjects.push(o);diagramSelected=diagramObjects.length-1;redrawDiagramCanvas();markDiagramChanged();}
