async function exportFullBackup(){
  const projects=estimatorDb ? await getAllProjects() : savedProjects();
  const payload={app:'Venture Home Estimator Pro',version:APP_VERSION,exportedAt:new Date().toISOString(),projects,current:backupCurrentState()};
  downloadBlob(JSON.stringify(payload,null,2),`venture_home_estimator_backup_${new Date().toISOString().slice(0,10)}.json`,'application/json');
  showNotice('Full backup downloaded. Keep it somewhere secure.','success');
}
async function importFullBackupFile(input){
  const file=input?.files?.[0]; if(!file) return;
  try{
    const payload=JSON.parse(await file.text());
    if(payload?.app!=='Venture Home Estimator Pro' || !Array.isArray(payload.projects) || !payload.current) throw new Error('invalid backup');
    if(!confirm(`Replace this browser's estimator data with ${payload.projects.length} project(s) from this backup?`)){input.value=''; return;}
    if(estimatorDb){
      await dbRequest('projects','readwrite',store=>store.clear());
      for(const project of payload.projects){if(project && project.id) await putProject(project);}
      await putSetting(PROJECT_INDEX_KEY,payload.projects.filter(project=>project && project.id).map(projectMeta));
      await putSetting(CURRENT_MEDIA_KEY,{sitePhotos:Array.isArray(payload.current.sitePhotos)?payload.current.sitePhotos:[],savedDiagrams:Array.isArray(payload.current.savedDiagrams)?payload.current.savedDiagrams:[]});
    } else {
      localStorage.setItem('vh_savedProjects',JSON.stringify(payload.projects));
      localStorage.setItem('vh_sitePhotos',JSON.stringify(Array.isArray(payload.current.sitePhotos)?payload.current.sitePhotos:[]));
      localStorage.setItem('vh_savedDiagrams',JSON.stringify(Array.isArray(payload.current.savedDiagrams)?payload.current.savedDiagrams:[]));
    }
    const current=payload.current;
    selected=Array.isArray(current.selected)?current.selected:[];
    localStorage.setItem('vh_selected',JSON.stringify(selected));
    localStorage.setItem('vh_projectName',String(current.projectName||''));
    localStorage.setItem('vh_projectAddress',String(current.projectAddress||''));
    localStorage.setItem('vh_workType',String(current.workType||''));
    localStorage.setItem('vh_customWorkType',String(current.customWorkType||''));
    localStorage.setItem('vh_projectDescription',String(current.workType||''));
    localStorage.setItem('vh_scopeOfWork',String(current.scopeOfWork||''));
    const restoredMarkup=Number(current.materialMarkup);
    localStorage.setItem('vh_materialMarkup',String(isAllowedMaterialMarkup(restoredMarkup)?restoredMarkup:DEFAULT_MATERIAL_MARKUP));
    localStorage.setItem(ZERO_MARKUP_LABOR_KEY,current.zeroMarkupLaborMultiplier===true?'true':'false');
    localStorage.setItem('vh_scopePresets',JSON.stringify(current.presets&&typeof current.presets==='object'?current.presets:{}));
    localStorage.setItem('vh_autoApplyPreset',current.autoApplyPreset===false?'false':'true');
    if(current.currentProjectId) localStorage.setItem('vh_currentProjectId',String(current.currentProjectId)); else localStorage.removeItem('vh_currentProjectId');
    showNotice('Backup restored. Reloading the estimator…','success');
    setTimeout(()=>location.reload(),700);
  }catch(error){showNotice('That file is not a valid Venture Home full backup. No data was changed.','warning');}
  finally{input.value='';}
}
